use crate::{s2_core::*,model::*,engine::Engine,recovery::sha,practical::{Plan,Practical}};
use std::{fs,path::PathBuf,sync::Arc};
const INPUT:&str="LOCAL_ONLY。架空の読書会。2026年11月14日 14:00〜16:00、森の図書室、当日受付。開催案内と運営チェックリストを画像付きHTMLにする。";
fn fixture()->(Arc<Engine>,PathBuf,Identity,String){
 let root=PathBuf::from(std::env::var_os("AI_GUILD_TEST_ROOT").expect("isolated test root")).join(format!("s2-core-{}",id()));fs::create_dir_all(&root).unwrap();fs::write(root.join(".ai-guild-qa"),"LOCAL_ONLY / no model or browser").unwrap();
 let workspace=root.join("quest");fs::create_dir(&workspace).unwrap();
 let png=fs::read(PathBuf::from(env!("CARGO_MANIFEST_DIR")).parent().unwrap().join("public/sprites/scholar.png")).unwrap();fs::write(root.join("source.png"),&png).unwrap();
 let b=Identity{job_id:id(),task_id:"image".into(),attempt:1};let core=Core::local(b.clone(),vec![ExpectedImage{artifact_id:"hero".into(),purpose:"LOCAL_ONLY試験画像。実生成素材ではない".into(),width:128,height:288,source_sha256:sha(&png)}]).unwrap();
 let mut w=crate::practical::workflow();w.workflow_id="s2-image-local-v1".into();w.workflow_name="画像付きHTML / LOCAL_ONLY".into();w.nodes[0].node_id="image".into();w.nodes[0].label="素材受領・素材C".into();w.nodes[0].sprite_key="artist".into();w.nodes[0].executor="manual".into();w.nodes[0].output_artifacts=vec!["hero.png".into()];w.nodes[1].dependencies=vec!["image".into()];w.nodes[1].input_artifacts=vec!["hero.png".into()];w.edges[0].from_node_id="image".into();w.edges[0].edge_id="image-writing".into();
 let plan=Plan{production_constraints:vec![],title:"架空の読書会".into(),requirements:vec!["2026年11月14日".into(),"14:00〜16:00".into(),"森の図書室".into(),"当日受付".into(),"架空".into()],checklist:vec!["受付を準備する".into(),"会場を整える".into(),"終了後に片付ける".into()]};
 let raw=format!("<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>架空の読書会</title><style>body{{background:#fff8ec;color:#182d38;font-family:sans-serif;line-height:1.8;margin:2rem}}main{{max-width:960px;margin:auto}}section{{padding:1rem;margin:1rem 0;background:#fff}}img{{max-width:100%;height:auto}}h1{{font-size:2rem}}.notice{{color:#804500}}</style></head><body><main><h1>架空の読書会</h1><p class=\"notice\">LOCAL_ONLY / オフライン試験。AI生成・自動回収の実証ではありません。</p><section aria-labelledby=\"info\"><h2 id=\"info\">開催案内</h2><p>{}</p><figure><img src=\"assets/image-1-hero.png\" alt=\"隔離試験用のギルドキャラクター。実制作の挿絵ではありません\" width=\"128\" height=\"288\"><figcaption>LOCAL_ONLY：既存の試験用素材</figcaption></figure></section><section><h2>運営チェックリスト</h2><ul>{}</ul></section></main></body></html>",plan.requirements.join(" · "),plan.checklist.iter().map(|x|format!("<li>{x}</li>")).collect::<String>());
 let nodes=w.nodes.iter().map(|n|(n.node_id.clone(),Run{attempt:1,..Run::default()})).collect();let j=Job{job_id:b.job_id.clone(),workflow_id:w.workflow_id.clone(),workflow:w,status:"running".into(),mode:"local_only".into(),instruction:INPUT.into(),started_at:now(),ended_at:None,workspace:workspace.to_string_lossy().into(),thread_id:None,turn_id:None,active_node_id:Some("image".into()),nodes,artifacts:vec![],stop_requested:false,pause_requested:false,practical:Some(Practical{version:2,original_instruction:INPUT.into(),turn_starts:0,max_turn_starts:0,plan:Some(plan)}),quality:None,recovery:None,collaboration:Some(core)};
 let e=Engine::open(&root,None).unwrap();e.update(|s|{s.job=Some(j);Ok(())}).unwrap();(e,root,b,raw)
}
fn review(p:&std::path::Path,hash:&str)->PathBuf{let path=p.join(format!("review-{hash}.json"));fs::write(&path,serde_json::to_vec_pretty(&Review{subject_sha256:hash.into(),verdict:"PASS".into(),reviewer:"OFFLINE_TEST_FIXTURE".into(),rationale:"Synthetic gate input only; actual visual evidence is a separate native/UI acceptance".into()}).unwrap()).unwrap();path}
fn received(e:&Engine,p:&std::path::Path,b:&Identity){e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).unwrap();let h=e.snapshot().job.unwrap().collaboration.unwrap().receipts[0].sha256.clone();e.review_local_material(b.clone(),"hero".into(),review(p,&h)).unwrap();}
fn record(p:&std::path::Path,name:&str,v:serde_json::Value){fs::write(p.join(format!("{name}.json")),serde_json::to_vec_pretty(&v).unwrap()).unwrap();}
#[test]fn s2_local_image_html_e2e_restart_and_finish(){
 let(e,p,b,raw)=fixture();received(&e,&p,&b);e.integrate_local_product(b.clone(),raw.clone()).unwrap();let j=e.snapshot().job.unwrap();assert_eq!(j.quality.as_ref().unwrap().display_status,"NOT_VERIFIED");assert_ne!(j.status,"completed");verify_product(&j).unwrap();drop(e);
 let e=Engine::open(&p,None).unwrap();e.recover_local_core(b.clone()).unwrap();let display=review(&p,&sha(raw.as_bytes()));e.finish_local_product(b.clone(),display,p.join("source.png")).unwrap();let j=e.snapshot().job.unwrap();assert_eq!(j.status,"completed");assert_eq!(j.collaboration.as_ref().unwrap().stage,"DONE_LOCAL_ONLY");drop(e);
 let e=Engine::open(&p,None).unwrap();verify_product(&e.snapshot().job.unwrap()).unwrap();let count=e.snapshot().events.len();e.recover_local_core(b.clone()).unwrap();assert_eq!(e.snapshot().events.len(),count);
 record(&p,"e2e-result",serde_json::json!({"classification":"LOCAL_ONLY","status":"PASS","visualGate":"SYNTHETIC_FIXTURE_ONLY_NOT_UI_EVIDENCE","jobId":b.job_id,"taskId":b.task_id,"attempt":b.attempt,"htmlSha256":sha(raw.as_bytes()),"inference":0,"send":0,"generation":0,"download":0,"restart":true,"print":"N/A","dataPath":p}));
 let before=e.snapshot();let file=PathBuf::from(&before.job.as_ref().unwrap().workspace).join("event.html");fs::write(&file,"tampered after completion").unwrap();assert!(e.recover_local_core(b).is_err());assert_eq!(e.snapshot().events.len(),before.events.len());assert_eq!(e.snapshot().job.unwrap().collaboration.unwrap().failures.len(),before.job.unwrap().collaboration.unwrap().failures.len());fs::write(file,raw).unwrap();
}
#[test]fn s2_wrong_identity_duplicate_receipt_download_and_missing_hash(){
 let(e,p,b,_)=fixture();for field in ["job","task","attempt"]{let mut wrong=b.clone();match field{"job"=>wrong.job_id="wrong".into(),"task"=>wrong.task_id="wrong".into(),_=>wrong.attempt=2}assert!(e.receive_local_material(wrong,"hero".into(),p.join("source.png")).is_err());}
 e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).unwrap();let before=e.snapshot();fs::copy(p.join("source.png"),p.join("duplicate-download.png")).unwrap();e.receive_local_material(b.clone(),"hero".into(),p.join("duplicate-download.png")).unwrap();assert_eq!(e.snapshot().job.unwrap().artifacts.len(),1);assert_eq!(before.events.len(),e.snapshot().events.len());
 let j=e.snapshot().job.unwrap();let target=PathBuf::from(&j.workspace).join("assets/image-1-hero.png");fs::write(&target,b"tamper").unwrap();assert!(e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).is_err());fs::remove_file(target).unwrap();assert!(e.recover_local_core(b).is_err());
 record(&p,"recovery-negative-result",serde_json::json!({"classification":"LOCAL_ONLY","wrongJob":true,"wrongTask":true,"wrongAttempt":true,"duplicateReceiptIdempotent":true,"duplicateDownloadResultNoNewDownload":true,"tamperRejected":true,"missingRejected":true,"download":0}));
}
#[test]fn s2_html_image_policy_manifest_and_material_gate(){
 let(e,p,b,raw)=fixture();assert!(e.integrate_local_product(b.clone(),raw.clone()).is_err());e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).unwrap();assert!(e.integrate_local_product(b.clone(),raw.clone()).is_err());received(&e,&p,&b);
 let mut rejected=vec![];for src in ["../source.png","/source.png","C:/x.png","file:///x.png","https://example.invalid/x.png","//example.invalid/x","assets/unregistered.png","assets/%2e%2e/x.png","assets/image-1-hero.png?x=1","assets\\image-1-hero.png","data:image/png;base64,x"]{assert!(e.integrate_local_product(b.clone(),raw.replace("assets/image-1-hero.png",src)).is_err(),"accepted {src}");rejected.push(src);}
 for insert in ["<script>1</script>","<svg onload='x'></svg>","<iframe></iframe>","<img src='assets/image-1-hero.png' onerror='x' alt='x'>","<img src='assets/image-1-hero.png' srcset='https://x.invalid/y' alt='x'>"]{assert!(e.integrate_local_product(b.clone(),raw.replace("<main>",&format!("<main>{insert}"))).is_err());}
 assert!(e.integrate_local_product(b.clone(),raw.replace("<img src=\"assets/image-1-hero.png\" alt=\"隔離試験用のギルドキャラクター。実制作の挿絵ではありません\" width=\"128\" height=\"288\">","")).is_err());
 e.integrate_local_product(b.clone(),raw.clone()).unwrap();let j=e.snapshot().job.unwrap();let mut wrong=j.clone();wrong.artifacts[0].sha256="0".repeat(64);assert!(verify_product(&wrong).is_err());let mut wrong=j.clone();wrong.collaboration.as_mut().unwrap().receipts[0].identity.attempt=2;assert!(verify_product(&wrong).is_err());
 record(&p,"policy-result",serde_json::json!({"classification":"LOCAL_ONLY","externalTraversalUnregisteredRejected":rejected,"scriptRejected":true,"materialCRequired":true,"missingReferenceRejected":true,"manifestDriftRejected":true,"wrongAttemptRejected":true,"validCssAriaAndImage":"PASS","print":"N/A"}));
}
#[test]fn s2_crash_windows_recover_same_task_without_ai_or_download(){
 for stage in ["receipt.after_intent","receipt.after_file","integration.after_intent","integration.after_file","manifest.after_file"]{
  let(e,p,b,raw)=fixture();if stage.starts_with("receipt"){
   FAULT.with(|f|*f.borrow_mut()=Some(stage));assert!(e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).is_err());FAULT.with(|f|*f.borrow_mut()=None);
  }else{received(&e,&p,&b);FAULT.with(|f|*f.borrow_mut()=Some(stage));if stage.starts_with("integration"){assert!(e.integrate_local_product(b.clone(),raw.clone()).is_err());}else{e.integrate_local_product(b.clone(),raw.clone()).unwrap();assert!(e.finish_local_product(b.clone(),review(&p,&sha(raw.as_bytes())),p.join("source.png")).is_err());}FAULT.with(|f|*f.borrow_mut()=None);}
  drop(e);let e=Engine::open(&p,None).unwrap();e.recover_local_core(b.clone()).unwrap();if stage.starts_with("receipt"){received(&e,&p,&b);e.integrate_local_product(b.clone(),raw.clone()).unwrap();}else if !stage.starts_with("manifest"){assert_eq!(e.snapshot().job.unwrap().quality.unwrap().machine_status,"PASS");}
  let j=e.snapshot().job.unwrap();assert_eq!(j.collaboration.as_ref().unwrap().identity,b);if stage!="manifest.after_file"{assert!(!j.collaboration.as_ref().unwrap().failures.is_empty());}verify_product(&j).unwrap();
  record(&p,"crash-result",serde_json::json!({"classification":"LOCAL_ONLY","fault":stage,"sameJobTaskAttempt":true,"recovery":"PASS","inference":0,"send":0,"generation":0,"download":0,"failureHistoryRetained":true}));
 }
}
#[test]fn s2_png_full_decode_and_symlink_reparse_refusal(){
 let(e,p,b,raw)=fixture();let source=fs::read(p.join("source.png")).unwrap();for bad in [source[..source.len()/2].to_vec(),b"\x89PNG\r\n\x1a\ninvalid".to_vec()]{assert!(crate::engine::inspect_image_bytes(&bad).is_err());}
 received(&e,&p,&b);let j=e.snapshot().job.unwrap();let root=PathBuf::from(&j.workspace);let assets=root.join("assets");fs::rename(&assets,root.join("real-assets")).unwrap();
 #[cfg(windows)]{let status=std::process::Command::new("cmd.exe").args(["/c","mklink","/J"]).arg(&assets).arg(root.join("real-assets")).status().unwrap();assert!(status.success());}
 #[cfg(not(windows))]std::os::unix::fs::symlink(root.join("real-assets"),&assets).unwrap();
 assert!(e.integrate_local_product(b,raw).is_err());record(&p,"reparse-result",serde_json::json!({"classification":"LOCAL_ONLY","internalJunctionRejected":true,"truncatedPngRejected":true,"status":"PASS"}));
}
#[test]fn s2_pending_copy_recovers_without_original_and_partial_temp_is_preserved(){
 let(e,p,b,raw)=fixture();FAULT.with(|f|*f.borrow_mut()=Some("receipt.after_file"));assert!(e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).is_err());FAULT.with(|f|*f.borrow_mut()=None);fs::remove_file(p.join("source.png")).unwrap();drop(e);
 let e=Engine::open(&p,None).unwrap();e.recover_local_core(b.clone()).unwrap();let h=e.snapshot().job.unwrap().collaboration.unwrap().receipts[0].sha256.clone();e.review_local_material(b.clone(),"hero".into(),review(&p,&h)).unwrap();let temp=p.join("quest/event.crash.tmp");fs::write(&temp,"partial bytes preserved").unwrap();e.integrate_local_product(b.clone(),raw).unwrap();assert_eq!(fs::read_to_string(temp).unwrap(),"partial bytes preserved");assert!(e.control("retry".into()).is_err());
 record(&p,"copy-recovery-result",serde_json::json!({"classification":"LOCAL_ONLY","missingOriginalReusedSavedCopy":true,"partialTempPreserved":true,"sameTask":true,"noInferenceRetry":true,"status":"PASS"}));
}
#[test]fn s2_quantity_dimensions_and_negative_content_review(){
 let(e,p,b,raw)=fixture();e.update(|s|{s.job.as_mut().unwrap().collaboration.as_mut().unwrap().expected[0].width=129;Ok(())}).unwrap();assert!(e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).is_err());e.update(|s|{let c=s.job.as_mut().unwrap().collaboration.as_mut().unwrap();c.expected[0].width=128;let mut other=c.expected[0].clone();other.artifact_id="second".into();c.expected.push(other);Ok(())}).unwrap();e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).unwrap();let h=e.snapshot().job.unwrap().collaboration.unwrap().receipts[0].sha256.clone();let r=review(&p,&h);let mut bad:Review=serde_json::from_slice(&fs::read(&r).unwrap()).unwrap();bad.verdict="NG".into();fs::write(&r,serde_json::to_vec(&bad).unwrap()).unwrap();assert!(e.review_local_material(b.clone(),"hero".into(),r).is_err());e.review_local_material(b.clone(),"hero".into(),review(&p,&h)).unwrap();assert!(e.integrate_local_product(b,raw).is_err());
 record(&p,"material-negative-result",serde_json::json!({"classification":"LOCAL_ONLY","wrongDimensionsRejected":true,"negativeContentRejected":true,"quantityShortageRejected":true,"status":"PASS"}));
}
#[test]fn s2_receipt_before_c_restart_does_not_require_a_new_task(){
 let(e,p,b,raw)=fixture();e.receive_local_material(b.clone(),"hero".into(),p.join("source.png")).unwrap();drop(e);let e=Engine::open(&p,None).unwrap();e.recover_local_core(b.clone()).unwrap();let h=e.snapshot().job.unwrap().collaboration.unwrap().receipts[0].sha256.clone();e.review_local_material(b.clone(),"hero".into(),review(&p,&h)).unwrap();e.integrate_local_product(b.clone(),raw).unwrap();assert_eq!(e.snapshot().job.unwrap().collaboration.unwrap().identity,b);record(&p,"receipt-restart-result",serde_json::json!({"classification":"LOCAL_ONLY","receiptBeforeCRecovery":"PASS","sameTask":true,"download":0}));
}
